-- 0005_reference_functions
--
-- The reference's maintenance discovery routines. Each is a single round-trip
-- that scans every schema for the work that is due; the body is the behaviour,
-- so it is reproduced rather than reimplemented.
--
-- Generated by scripts/reference_schema_migrations.py. Do not hand-edit.

DROP FUNCTION IF EXISTS banks_needing_consolidation();
DROP FUNCTION IF EXISTS mental_models_with_cron();
DROP FUNCTION IF EXISTS schemas_with_expired_operations(p_days integer);
DROP FUNCTION IF EXISTS schemas_with_expired_rows(p_table text, p_ts_col text, p_days integer);

CREATE OR REPLACE FUNCTION banks_needing_consolidation()
 RETURNS TABLE(schema_name text, bank_id text)
 LANGUAGE plpgsql
 STABLE
AS $function$
        DECLARE
            sch text;
            prev_lock_timeout text;
        BEGIN
            prev_lock_timeout := current_setting('lock_timeout');
            PERFORM set_config('lock_timeout', '250ms', true);
            FOR sch IN
                SELECT n.nspname
                FROM pg_class c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE c.relname = 'memory_units' AND c.relkind = 'r'
            LOOP
                BEGIN
                    RETURN QUERY EXECUTE format($q$
                        SELECT %1$L::text, b.bank_id
                        FROM %1$I.banks b
                        WHERE COALESCE(b.config -> 'enable_auto_consolidation', 'true'::jsonb) <> 'false'::jsonb
                          AND NOT EXISTS (
                              SELECT 1 FROM %1$I.async_operations o
                              WHERE o.bank_id = b.bank_id
                                AND o.operation_type = 'consolidation'
                                AND o.status IN ('pending', 'processing')
                          )
                          AND EXISTS (
                              SELECT 1 FROM %1$I.memory_units m
                              WHERE m.bank_id = b.bank_id
                                AND m.consolidated_at IS NULL
                                AND m.fact_type IN ('experience', 'world')
                          )
                          AND (
                              EXISTS (
                                  SELECT 1 FROM (
                                      SELECT m.consolidation_failed_at
                                      FROM %1$I.memory_units m
                                      WHERE m.bank_id = b.bank_id
                                        AND m.consolidated_at IS NULL
                                        AND m.fact_type IN ('experience', 'world')
                                      ORDER BY m.created_at DESC
                                      LIMIT 100
                                  ) newest
                                  WHERE newest.consolidation_failed_at IS NULL
                              )
                              OR (
                                  SELECT count(*) FROM %1$I.memory_units m
                                  WHERE m.bank_id = b.bank_id
                                    AND m.consolidated_at IS NULL
                                    AND m.fact_type IN ('experience', 'world')
                              ) > (
                                  SELECT count(*) FROM %1$I.memory_units f
                                  WHERE f.bank_id = b.bank_id
                                    AND f.consolidation_failed_at IS NOT NULL
                                    AND f.fact_type IN ('experience', 'world')
                              )
                          )
                    $q$, sch);

                EXCEPTION
                    -- Schema or its tables vanished between the pg_class
                    -- snapshot and this query (tenant dropped or migrating).
                    WHEN undefined_table OR invalid_schema_name OR undefined_column THEN
                        CONTINUE;
                    -- Schema is mid-DDL and holds (or has queued) an
                    -- AccessExclusiveLock. Skip it rather than wait: waiting is
                    -- what closes the deadlock cycle. deadlock_detected is
                    -- belt-and-braces for a cycle formed before lock_timeout.
                    WHEN lock_not_available OR deadlock_detected THEN
                        CONTINUE;
                END;
            END LOOP;
            PERFORM set_config('lock_timeout', prev_lock_timeout, true);
        END;
        $function$
;

CREATE OR REPLACE FUNCTION mental_models_with_cron()
 RETURNS TABLE(schema_name text, bank_id text, mental_model_id text, refresh_cron text, last_refreshed_at timestamp with time zone, full_refresh_cron text, last_full_refreshed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
        DECLARE
            sch text;
            prev_lock_timeout text;
        BEGIN
            prev_lock_timeout := current_setting('lock_timeout');
            PERFORM set_config('lock_timeout', '250ms', true);
            FOR sch IN
                SELECT n.nspname
                FROM pg_class c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE c.relname = 'mental_models' AND c.relkind = 'r'
            LOOP
                BEGIN
                    RETURN QUERY EXECUTE format($q$
                        SELECT %1$L::text, mm.bank_id::text, mm.id::text,
                               mm.trigger->>'refresh_cron', mm.last_refreshed_at,
                               mm.trigger->>'full_refresh_cron', mm.last_full_refreshed_at
                        FROM %1$I.mental_models mm
                        WHERE (COALESCE(mm.trigger->>'refresh_cron', '') <> ''
                               OR COALESCE(mm.trigger->>'full_refresh_cron', '') <> '')
                          AND NOT EXISTS (
                              SELECT 1 FROM %1$I.async_operations o
                              WHERE o.bank_id = mm.bank_id
                                AND o.operation_type = 'refresh_mental_model'
                                AND o.status IN ('pending', 'processing')
                                AND o.task_payload->>'mental_model_id' = mm.id::text
                          )
                    $q$, sch);

                EXCEPTION
                    WHEN undefined_table OR invalid_schema_name OR undefined_column THEN
                        CONTINUE;
                    WHEN lock_not_available OR deadlock_detected THEN
                        CONTINUE;
                END;
            END LOOP;
            PERFORM set_config('lock_timeout', prev_lock_timeout, true);
        END;
        $function$
;

CREATE OR REPLACE FUNCTION schemas_with_expired_operations(p_days integer)
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE
AS $function$
        DECLARE
            sch text;
            has_expired boolean;
            prev_lock_timeout text;
        BEGIN
            -- Zero (or negative) retention means "keep forever": report nothing
            -- so the caller skips the sweep entirely.
            IF p_days IS NULL OR p_days <= 0 THEN
                RETURN;
            END IF;
            prev_lock_timeout := current_setting('lock_timeout');
            PERFORM set_config('lock_timeout', '250ms', true);
            FOR sch IN
                SELECT n.nspname
                FROM pg_class c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE c.relname = 'async_operations' AND c.relkind = 'r'
            LOOP
                BEGIN
                    -- Matches the worker's prune predicate: only terminal rows
                    -- are eligible, so a schema holding nothing but pending or
                    -- processing work is correctly reported as having nothing
                    -- to prune. Uses idx_async_operations_terminal_cleanup.
                    EXECUTE format(
                        'SELECT EXISTS ('
                        '  SELECT 1 FROM %I.async_operations'
                        '  WHERE status IN (''completed'', ''failed'', ''cancelled'')'
                        '    AND updated_at < NOW() - make_interval(days => $1)'
                        ')',
                        sch
                    ) INTO has_expired USING p_days;

                EXCEPTION
                    -- Schema or its tables vanished between the pg_class
                    -- snapshot and this query (tenant dropped or migrating).
                    WHEN undefined_table OR invalid_schema_name OR undefined_column THEN
                        CONTINUE;
                    -- Schema is mid-DDL and holds (or has queued) an
                    -- AccessExclusiveLock. Skip it rather than wait: waiting is
                    -- what closes the deadlock cycle. deadlock_detected is
                    -- belt-and-braces for a cycle formed before lock_timeout.
                    WHEN lock_not_available OR deadlock_detected THEN
                        CONTINUE;
                END;
                IF has_expired THEN
                    RETURN NEXT sch;
                END IF;
            END LOOP;
            PERFORM set_config('lock_timeout', prev_lock_timeout, true);
        END;
        $function$
;

CREATE OR REPLACE FUNCTION schemas_with_expired_rows(p_table text, p_ts_col text, p_days integer)
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE
AS $function$
        DECLARE
            sch text;
            has_expired boolean;
            prev_lock_timeout text;
        BEGIN
            IF p_days IS NULL OR p_days <= 0 THEN
                RETURN;
            END IF;
            prev_lock_timeout := current_setting('lock_timeout');
            PERFORM set_config('lock_timeout', '250ms', true);
            FOR sch IN
                SELECT n.nspname
                FROM pg_class c
                JOIN pg_namespace n ON n.oid = c.relnamespace
                WHERE c.relname = p_table AND c.relkind = 'r'
            LOOP
                BEGIN
                    EXECUTE format(
                        'SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I < NOW() - make_interval(days => $1))',
                        sch, p_table, p_ts_col
                    ) INTO has_expired USING p_days;

                EXCEPTION
                    -- Schema or its tables vanished between the pg_class
                    -- snapshot and this query (tenant dropped or migrating).
                    WHEN undefined_table OR invalid_schema_name OR undefined_column THEN
                        CONTINUE;
                    -- Schema is mid-DDL and holds (or has queued) an
                    -- AccessExclusiveLock. Skip it rather than wait: waiting is
                    -- what closes the deadlock cycle. deadlock_detected is
                    -- belt-and-braces for a cycle formed before lock_timeout.
                    WHEN lock_not_available OR deadlock_detected THEN
                        CONTINUE;
                END;
                IF has_expired THEN
                    RETURN NEXT sch;
                END IF;
            END LOOP;
            PERFORM set_config('lock_timeout', prev_lock_timeout, true);
        END;
        $function$

;
